const fmtDate = (value?: string) => value ? new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value)) : '—';
const fmtTime = (value?: string) => value ? new Intl.DateTimeFormat('en', { hour: 'numeric', minute: '2-digit' }).format(new Date(value)) : '—';
const pct = (value?: number) => `${Math.round((value ?? 0) * (value && value <= 1 ? 100 : 1))}%`;
const shortUrl = (url: string) => url.replace(/^https?:\/\//, '').replace(/\/$/, '');
const isPhishing = (verdict?: string) => verdict === 'phishing';

function Logo({ light = false }: { light?: boolean }) {
  return (
    <Link href="/" data-testid="link-logo" className="focus-ring flex items-center gap-3">
      <span className={`grid h-9 w-9 place-items-center rounded-xl ${light ? 'bg-[hsl(var(--sidebar-primary))] text-[hsl(var(--sidebar-primary-foreground))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]'}`}>
        <ShieldCheck size={20} strokeWidth={2.4} />
      </span>
      <span className={`text-[15px] font-extrabold tracking-[-.03em] ${light ? 'text-[hsl(var(--sidebar-foreground))]' : ''}`}>phish<span className={light ? 'text-[hsl(var(--sidebar-primary))]' : 'text-[hsl(var(--primary))]'}>guard</span></span>
    </Link>
  );
}

function Button({ children, variant = 'primary', className = '', type = 'button', onClick, disabled, testId = 'button-action' }: { children: ReactNode; variant?: 'primary' | 'soft' | 'outline' | 'ghost' | 'danger'; className?: string; type?: 'button' | 'submit'; onClick?: () => void; disabled?: boolean; testId?: string }) {
  const styles = {
    primary: 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] shadow-[0_8px_22px_rgba(29,113,100,.16)] hover:-translate-y-0.5 hover:brightness-105',
    soft: 'bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))] hover:bg-[hsl(var(--secondary)/.72)]',
    outline: 'border border-[hsl(var(--border))] bg-[hsl(var(--card)/.76)] text-[hsl(var(--foreground))] hover:border-[hsl(var(--primary)/.5)] hover:bg-[hsl(var(--secondary)/.4)]',
    ghost: 'text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--secondary)/.65)] hover:text-[hsl(var(--foreground))]',
    danger: 'bg-[hsl(var(--destructive)/.1)] text-[hsl(var(--destructive))] hover:bg-[hsl(var(--destructive)/.16)]',
  };
  return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId} className={`focus-ring inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-[13px] font-bold transition-all disabled:cursor-not-allowed disabled:opacity-55 ${styles[variant]} ${className}`}>{children}</button>;
}

function Card({ children, className = '', testId }: { children: ReactNode; className?: string; testId?: string }) {
  return <div data-testid={testId} className={`rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] shadow-[var(--shadow-card)] ${className}`}>{children}</div>;
}

function StatusPill({ verdict }: { verdict?: string }) {
  const bad = isPhishing(verdict);
  return <span data-testid={`status-verdict-${verdict ?? 'unknown'}`} className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold ${bad ? 'bg-[hsl(var(--destructive)/.12)] text-[hsl(var(--destructive))]' : 'bg-[hsl(var(--primary)/.11)] text-[hsl(var(--primary))]'}`}>
    {bad ? <ShieldAlert size={13} /> : <CheckCircle2 size={13} />} {bad ? 'Phishing signal' : 'Looks safe'}
  </span>;
}

function LoadingState({ label = 'Loading your security picture' }: { label?: string }) {
  return <div className="space-y-3" data-testid="state-loading"><div className="h-24 animate-pulse rounded-2xl bg-[hsl(var(--muted))]" /><div className="h-4 w-2/3 animate-pulse rounded bg-[hsl(var(--muted))]" /><p className="text-xs text-[hsl(var(--muted-foreground))]">{label}…</p></div>;
}

function ErrorState({ onRetry, label = 'We could not load this view.' }: { onRetry?: () => void; label?: string }) {
  return <Card className="border-[hsl(var(--destructive)/.25)] p-8 text-center" testId="state-error"><div className="mx-auto mb-3 grid h-11 w-11 place-items-center rounded-full bg-[hsl(var(--destructive)/.1)] text-[hsl(var(--destructive))]"><RefreshCw size={19} /></div><h3 className="font-bold">{label}</h3><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">Try again or check your connection. Your saved scans are not affected.</p>{onRetry && <Button variant="outline" onClick={onRetry} className="mt-5" testId="button-retry">Try again</Button>}</Card>;
}

function EmptyState({ title, copy, action }: { title: string; copy: string; action?: ReactNode }) {
  return <Card className="grid place-items-center p-12 text-center" testId="state-empty"><div className="mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Radar size={22} /></div><h3 className="font-bold">{title}</h3><p className="mt-1 max-w-sm text-sm text-[hsl(var(--muted-foreground))]">{copy}</p>{action && <div className="mt-5">{action}</div>}</Card>;
}

