  const [demoUrl, setDemoUrl] = useState('https://accounts.example.com/sign-in');
  return <div className="min-h-[100dvh] overflow-hidden bg-[hsl(var(--background))]"><PublicHeader /><section className="relative mx-auto max-w-6xl px-5 pb-20 pt-12 md:px-8 md:pb-28 md:pt-20"><div className="pointer-events-none absolute -right-28 top-0 h-[540px] w-[540px] rounded-full bg-[hsl(var(--primary)/.09)] blur-3xl" /><div className="relative grid items-center gap-14 lg:grid-cols-[1.03fr_.97fr]"><div className="animate-rise"><div className="mb-7 inline-flex items-center gap-2 rounded-full border border-[hsl(var(--primary)/.2)] bg-[hsl(var(--primary)/.07)] px-3 py-1.5 text-[11px] font-bold text-[hsl(var(--primary))]"><span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--primary))]" /> Built for clear decisions, not panic</div><h1 className="max-w-[660px] text-5xl font-extrabold leading-[1.02] tracking-[-.065em] text-[hsl(var(--foreground))] md:text-7xl">A second opinion for the links you <span className="text-[hsl(var(--primary))]">almost clicked.</span></h1><p className="mt-7 max-w-[520px] text-base leading-8 text-[hsl(var(--muted-foreground))]">PhishGuard reads the signals inside a URL and explains what they mean in plain language. No fear tactics. Just a calm, useful answer before you continue.</p><div className="mt-9 flex flex-wrap items-center gap-3"><Button onClick={() => setLocation('/scanner')} testId="button-start-scanning">Scan a URL <ArrowRight size={16} /></Button><Link href="/extension-preview" data-testid="link-see-extension" className="focus-ring inline-flex items-center gap-2 rounded-xl px-4 py-2.5 text-[13px] font-bold text-[hsl(var(--muted-foreground))] hover:text-[hsl(var(--foreground))]">See the browser helper <ChevronRight size={15} /></Link></div><div className="mt-10 flex items-center gap-5 text-[11px] text-[hsl(var(--muted-foreground))]"><div className="flex items-center gap-2"><LockKeyhole size={14} className="text-[hsl(var(--primary))]" /> Your URLs stay yours</div><div className="h-4 w-px bg-[hsl(var(--border))]" /><div className="flex items-center gap-2"><Gauge size={14} className="text-[hsl(var(--primary))]" /> Explainable results</div></div></div><div className="animate-rise stagger-2 relative"><div className="absolute -inset-5 rounded-[32px] bg-[hsl(var(--primary)/.08)] blur-2xl" /><Card className="relative overflow-hidden border-[hsl(var(--border)/.9)]"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] px-5 py-4"><div className="flex items-center gap-2"><div className="grid h-7 w-7 place-items-center rounded-lg bg-[hsl(var(--primary)/.12)] text-[hsl(var(--primary))]"><Radar size={15} /></div><span className="text-xs font-bold">Quick scan</span></div><div className={`flex items-center gap-1.5 text-[10px] font-bold ${health.isError ? 'text-[hsl(var(--muted-foreground))]' : 'text-[hsl(var(--primary))]'}`}><span className="h-1.5 w-1.5 rounded-full bg-current" /> {health.isError ? 'Demo mode' : 'Systems online'}</div></div><div className="grid-texture p-5 md:p-7"><label className="mono text-[10px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]">Paste a link to inspect</label><div className="mt-3 flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-2 shadow-sm"><Link2 size={17} className="ml-2 shrink-0 text-[hsl(var(--muted-foreground))]" /><input value={demoUrl} onChange={e => setDemoUrl(e.target.value)} data-testid="input-landing-url" className="min-w-0 flex-1 bg-transparent px-1 py-2 text-xs outline-none" /><Button onClick={() => setLocation(`/scanner?url=${encodeURIComponent(demoUrl)}`)} className="shrink-0 px-3 py-2" testId="button-analyze-landing">Analyze</Button></div><div className="mt-7 rounded-2xl border border-[hsl(var(--primary)/.2)] bg-[hsl(var(--primary)/.06)] p-5"><div className="flex items-start justify-between"><div><p className="text-[11px] font-bold text-[hsl(var(--primary))]">What you will get</p><p className="mt-2 text-lg font-extrabold tracking-[-.04em]">A decision you can trust.</p></div><div className="pulse-ring grid h-10 w-10 place-items-center rounded-full border border-[hsl(var(--primary)/.3)] text-[hsl(var(--primary))]"><ShieldCheck size={19} /></div></div><div className="mt-5 grid gap-3 text-xs text-[hsl(var(--muted-foreground))] sm:grid-cols-3"><div><p className="mb-1 font-bold text-[hsl(var(--foreground))]">01 / Signals</p>Domain, path and structure.</div><div><p className="mb-1 font-bold text-[hsl(var(--foreground))]">02 / Verdict</p>Safe or needs a closer look.</div><div><p className="mb-1 font-bold text-[hsl(var(--foreground))]">03 / Why</p>Plain-language reasoning.</div></div></div></div></Card></div></div></section><section id="how" className="border-y border-[hsl(var(--border))] bg-[hsl(var(--card)/.5)]"><div className="mx-auto grid max-w-6xl gap-0 px-5 md:grid-cols-3 md:px-8">{[['01', 'Start with the link', 'Paste anything that feels off. PhishGuard accepts the messy links real life throws at you.', Link2], ['02', 'See the reasoning', 'We separate URL signals from the machine learning prediction so the answer is never a black box.', FileSearch], ['03', 'Choose your next step', 'A clear risk level helps you pause, continue, or ask someone you trust.', CheckCircle2]].map(([number, title, copy, Icon], index) => <div key={number as string} className={`animate-rise stagger-${index + 1} border-[hsl(var(--border))] px-1 py-9 md:px-9 md:py-12 ${index < 2 ? 'md:border-r' : ''}`}><span className="mono text-[11px] font-bold text-[hsl(var(--primary))]">{number as string}</span><div className="mt-7 mb-4 grid h-10 w-10 place-items-center rounded-xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Icon size={18} /></div><h3 className="text-base font-extrabold tracking-[-.03em]">{title as string}</h3><p className="mt-2 max-w-xs text-sm leading-6 text-[hsl(var(--muted-foreground))]">{copy as string}</p></div>)}</div></section><section className="mx-auto max-w-6xl px-5 py-20 md:px-8 md:py-28"><div className="grid items-center gap-10 md:grid-cols-[.75fr_1.25fr]"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--primary))]">For curious humans</p><h2 className="mt-4 max-w-md text-3xl font-extrabold leading-tight tracking-[-.055em] md:text-4xl">Security tools should teach, not just judge.</h2><p className="mt-5 max-w-md text-sm leading-7 text-[hsl(var(--muted-foreground))]">Explore the individual URL features that influence a result, then build a better instinct for the next suspicious message.</p><Link href="/signup" data-testid="link-learn-signup" className="focus-ring mt-7 inline-flex items-center gap-2 text-sm font-bold text-[hsl(var(--primary))]">Make an account <ArrowRight size={15} /></Link></div><div className="grid gap-3 sm:grid-cols-2"><FeatureTile icon={Fingerprint} title="Identity signals" copy="Lookalike domains, unusual symbols and deceptive subdomains." /><FeatureTile icon={Network} title="Structure signals" copy="Length, redirects and patterns that deserve a pause." /><FeatureTile icon={Target} title="Model context" copy="See how the classifier and rules agree or differ." /><FeatureTile icon={BookOpen} title="Built to explain" copy="No mystery scores without the details behind them." /></div></div></section><footer className="border-t border-[hsl(var(--border))] px-5 py-7 md:px-8"><div className="mx-auto flex max-w-6xl flex-col justify-between gap-4 text-[11px] text-[hsl(var(--muted-foreground))] sm:flex-row"><Logo /><span>PhishGuard — a calmer way to check.</span></div></footer></div>;
