function LoginPage() {
  const [, setLocation] = useLocation();
  const login = useLogin();
  const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); login.mutate({ data: { email, password } }, { onSuccess: () => setLocation('/dashboard') }); };
  return <AuthLayout eyebrow="Welcome back" title="Good to see you." copy="Sign in to keep your scan history close and your next decision clear."><form onSubmit={submit} className="space-y-4"><Field label="Email address" value={email} onChange={setEmail} type="email" placeholder="you@example.com" testId="input-email" /><Field label="Password" value={password} onChange={setPassword} type="password" placeholder="At least 6 characters" testId="input-password" /><div className="flex justify-end"><Link href="/forgot-password" data-testid="link-forgot-password" className="text-xs font-bold text-[hsl(var(--primary))] hover:underline">Forgot password?</Link></div>{login.isError && <p className="rounded-xl bg-[hsl(var(--destructive)/.1)] px-3 py-2.5 text-xs font-semibold text-[hsl(var(--destructive))]" data-testid="status-login-error">We could not sign you in. Check your details and try again.</p>}<Button type="submit" disabled={login.isPending} className="mt-2 w-full" testId="button-submit-login">{login.isPending ? 'Signing you in…' : 'Sign in'} <ArrowRight size={15} /></Button></form><p className="mt-7 text-center text-xs text-[hsl(var(--muted-foreground))]">New to PhishGuard? <Link href="/signup" data-testid="link-create-account" className="font-bold text-[hsl(var(--primary))]">Create an account</Link></p></AuthLayout>;
}

function SignupPage() {
  const [, setLocation] = useLocation();
  const signup = useSignup();
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); signup.mutate({ data: { name, email, password } }, { onSuccess: () => setLocation('/dashboard') }); };
  return <AuthLayout eyebrow="Start with clarity" title="Make a better call." copy="Create a private workspace for your scans, patterns and growing security instinct."><form onSubmit={submit} className="space-y-4"><Field label="Your name" value={name} onChange={setName} placeholder="How should we call you?" testId="input-name" /><Field label="Email address" value={email} onChange={setEmail} type="email" placeholder="you@example.com" testId="input-signup-email" /><Field label="Password" value={password} onChange={setPassword} type="password" placeholder="At least 6 characters" testId="input-signup-password" />{signup.isError && <p className="rounded-xl bg-[hsl(var(--destructive)/.1)] px-3 py-2.5 text-xs font-semibold text-[hsl(var(--destructive))]" data-testid="status-signup-error">That account could not be created. Please check the fields and try again.</p>}<Button type="submit" disabled={signup.isPending} className="mt-2 w-full" testId="button-submit-signup">{signup.isPending ? 'Creating workspace…' : 'Create workspace'} <ArrowRight size={15} /></Button></form><p className="mt-7 text-center text-xs text-[hsl(var(--muted-foreground))]">Already have an account? <Link href="/login" data-testid="link-existing-account" className="font-bold text-[hsl(var(--primary))]">Sign in</Link></p></AuthLayout>;
}

function Field({ label, value, onChange, placeholder, type = 'text', testId }: { label: string; value: string; onChange: (value: string) => void; placeholder: string; type?: string; testId: string }) {
  return <label className="block"><span className="mb-2 block text-xs font-bold">{label}</span><input required type={type} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} data-testid={testId} className="focus-ring h-12 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-4 text-sm outline-none transition placeholder:text-[hsl(var(--muted-foreground)/.65)] focus:border-[hsl(var(--primary))]" /></label>;
}

function PageHeading({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--primary))]">{eyebrow}</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-.06em] md:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[hsl(var(--muted-foreground))]">{copy}</p></div>{action}</div>;
}

function Metric({ label, value, note, icon: Icon, tone = 'primary' }: { label: string; value: string | number; note: string; icon: LucideIcon; tone?: 'primary' | 'amber' | 'red' }) {
  const color = tone === 'red' ? 'text-[hsl(var(--destructive))] bg-[hsl(var(--destructive)/.1)]' : tone === 'amber' ? 'text-[hsl(var(--accent-foreground))] bg-[hsl(var(--accent)/.2)]' : 'text-[hsl(var(--primary))] bg-[hsl(var(--primary)/.11)]';
  return <Card className="p-5 transition hover:-translate-y-0.5" testId={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-[hsl(var(--muted-foreground))]">{label}</p><p className="mt-3 text-3xl font-extrabold tracking-[-.06em]">{value}</p></div><div className={`grid h-9 w-9 place-items-center rounded-xl ${color}`}><Icon size={17} /></div></div><p className="mt-4 text-[11px] text-[hsl(var(--muted-foreground))]">{note}</p></Card>;
}

function ScanRow({ scan }: { scan: any }) {
  return <Link href={`/features/${scan.id}`} data-testid={`link-scan-${scan.id}`} className="group flex items-center gap-3 border-b border-[hsl(var(--border)/.7)] px-5 py-4 transition last:border-0 hover:bg-[hsl(var(--secondary)/.35)]"><div className={`grid h-8 w-8 shrink-0 place-items-center rounded-lg ${isPhishing(scan.verdict) ? 'bg-[hsl(var(--destructive)/.1)] text-[hsl(var(--destructive))]' : 'bg-[hsl(var(--primary)/.1)] text-[hsl(var(--primary))]'}`}>{isPhishing(scan.verdict) ? <ShieldAlert size={15} /> : <CheckCircle2 size={15} />}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{shortUrl(scan.url)}</p><p className="mt-1 text-[10px] text-[hsl(var(--muted-foreground))]">{fmtDate(scan.createdAt)} at {fmtTime(scan.createdAt)}</p></div><div className="hidden text-right sm:block"><StatusPill verdict={scan.verdict} /><p className="mono mt-1 text-[10px] text-[hsl(var(--muted-foreground))]">{Math.round(scan.confidence * (scan.confidence <= 1 ? 100 : 1))}% confidence</p></div><ChevronRight size={16} className="text-[hsl(var(--muted-foreground)/.5)] transition group-hover:translate-x-0.5 group-hover:text-[hsl(var(--primary))]" /></Link>;
}

function DashboardPage() {
  const [, setLocation] = useLocation();
  const stats = useGetDashboardStats({ query: { queryKey: getGetDashboardStatsQueryKey(), retry: 1 } });
  const data = stats.data;
  return <><PageHeading eyebrow="Your security cockpit" title="See the signal, not the noise." copy="A quick read on the links you have checked and the patterns worth remembering." action={<Button onClick={() => setLocation('/scanner')} testId="button-dashboard-scan"><Radar size={16} /> Scan a new URL</Button>} />{stats.isLoading ? <LoadingState /> : stats.isError ? <ErrorState onRetry={() => stats.refetch()} /> : data ? <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="URLs checked" value={data.totalScanned} note="Across your workspace" icon={Activity} /><Metric label="Phishing signals" value={data.maliciousDetected} note={`${pct(data.phishingPercent)} of all scans`} icon={ShieldAlert} tone="red" /><Metric label="Safe to continue" value={data.safeUrls} note={`${pct(data.safePercent)} of all scans`} icon={CheckCircle2} /><Metric label="Model accuracy" value={pct(data.modelAccuracy)} note="On the latest test set" icon={Gauge} tone="amber" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.24fr_.76fr]"><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] px-5 py-4"><div><h2 className="text-sm font-extrabold">Recent scans</h2><p className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">Your latest decisions, with the why one click away.</p></div><Link href="/logs" data-testid="link-view-all-scans" className="text-[11px] font-bold text-[hsl(var(--primary))]">View all</Link></div>{data.recentScans?.length ? data.recentScans.map((scan: any) => <ScanRow key={scan.id} scan={scan} />) : <div className="p-8"><EmptyState title="Your scan history starts here" copy="Check a link that feels uncertain and your result will appear in this space." action={<Button onClick={() => setLocation('/scanner')} testId="button-empty-scan">Scan your first URL</Button>} /></div>}</Card><Card className="overflow-hidden"><div className="border-b border-[hsl(var(--border))] px-5 py-4"><h2 className="text-sm font-extrabold">Your scan mix</h2><p className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">A balanced view of what you are encountering.</p></div><div className="p-6"><div className="relative mx-auto grid h-44 w-44 place-items-center rounded-full" style={{ background: `conic-gradient(hsl(var(--primary)) 0 ${data.safePercent * (data.safePercent <= 1 ? 100 : 1)}%, hsl(var(--destructive)) ${data.safePercent * (data.safePercent <= 1 ? 100 : 1)}% 100%)` }}><div className="grid h-32 w-32 place-items-center rounded-full bg-[hsl(var(--card))] text-center"><span className="text-3xl font-extrabold tracking-[-.06em]">{pct(data.safePercent)}</span><span className="text-[10px] text-[hsl(var(--muted-foreground))]">safe checks</span></div></div><div className="mt-6 space-y-3 text-xs"><div className="flex justify-between"><span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[hsl(var(--primary))]" /> Safe links</span><strong>{pct(data.safePercent)}</strong></div><div className="flex justify-between"><span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[hsl(var(--destructive))]" /> Phishing signals</span><strong>{pct(data.phishingPercent)}</strong></div></div></div></Card></div></> : <EmptyState title="No dashboard data yet" copy="Your workspace is ready for its first scan." />}</>;
}

function ScannerPage() {
  const [, setLocation] = useLocation();
  const create = useCreateScan();
  const [url, setUrl] = useState(() => new URLSearchParams(window.location.search).get('url') ?? '');
  const [result, setResult] = useState<any>(null);
  const [example, setExample] = useState('safe');
  const runScan = (e?: FormEvent) => { e?.preventDefault(); if (!url.trim()) return; create.mutate({ data: { url: url.trim() } }, { onSuccess: scan => setResult(scan) }); };
  const useExample = (kind: 'safe' | 'phishing') => { setExample(kind); setUrl(kind === 'safe' ? 'https://www.nationalgeographic.com/' : 'https://secure-account-verification.example.net/login'); setResult(null); };
  return <><PageHeading eyebrow="URL scanner" title="Pause. Then decide." copy="Paste a URL below. We will inspect its structure, compare signals and explain the result without jargon." /><div className="grid gap-6 xl:grid-cols-[.82fr_1.18fr]"><Card className="p-6 md:p-8"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[hsl(var(--primary)/.11)] text-[hsl(var(--primary))]"><Radar size={19} /></div><div><h2 className="text-sm font-extrabold">Analyze a link</h2><p className="text-[11px] text-[hsl(var(--muted-foreground))]">Results are saved to your history.</p></div></div><form onSubmit={runScan} className="mt-7"><label className="mono text-[10px] uppercase tracking-[.15em] text-[hsl(var(--muted-foreground))]">URL to inspect</label><div className={`scan-beam mt-3 flex items-center gap-2 rounded-xl border bg-[hsl(var(--background))] p-2 transition ${create.isPending ? 'border-[hsl(var(--primary))]' : 'border-[hsl(var(--input))]'}`}><Link2 size={17} className="ml-2 shrink-0 text-[hsl(var(--muted-foreground))]" /><input required value={url} onChange={e => setUrl(e.target.value)} placeholder="https://example.com/account" data-testid="input-scan-url" className="min-w-0 flex-1 bg-transparent px-1 py-2.5 text-sm outline-none placeholder:text-[hsl(var(--muted-foreground)/.65)]" /><Button type="submit" disabled={create.isPending} className="shrink-0 px-3.5 py-2.5" testId="button-submit-scan">{create.isPending ? 'Checking…' : 'Analyze'} <ArrowRight size={14} /></Button></div></form>{create.isError && <div className="mt-4 rounded-xl bg-[hsl(var(--destructive)/.1)] p-3 text-xs leading-5 text-[hsl(var(--destructive))]" data-testid="status-scan-error"><strong>We could not complete that scan.</strong><br />Check that the URL includes a domain, then try again.</div>}<div className="mt-8 border-t border-[hsl(var(--border))] pt-6"><p className="text-xs font-bold">Need a starting point?</p><p className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">Use a harmless example to see how the explanation is structured.</p><div className="mt-3 grid gap-2"><button onClick={() => useExample('safe')} data-testid="button-example-safe" className={`focus-ring flex items-center justify-between rounded-xl border px-3 py-3 text-left transition ${example === 'safe' ? 'border-[hsl(var(--primary)/.4)] bg-[hsl(var(--primary)/.06)]' : 'border-[hsl(var(--border))] hover:bg-[hsl(var(--secondary)/.4)]'}`}><span className="flex items-center gap-2 text-xs font-bold"><CheckCircle2 size={15} className="text-[hsl(var(--primary))]" /> A familiar public site</span><ChevronRight size={14} className="text-[hsl(var(--muted-foreground))]" /></button><button onClick={() => useExample('phishing')} data-testid="button-example-phishing" className={`focus-ring flex items-center justify-between rounded-xl border px-3 py-3 text-left transition ${example === 'phishing' ? 'border-[hsl(var(--destructive)/.35)] bg-[hsl(var(--destructive)/.06)]' : 'border-[hsl(var(--border))] hover:bg-[hsl(var(--secondary)/.4)]'}`}><span className="flex items-center gap-2 text-xs font-bold"><ShieldAlert size={15} className="text-[hsl(var(--destructive))]" /> A suspicious account link</span><ChevronRight size={14} className="text-[hsl(var(--muted-foreground))]" /></button></div></div></Card><div>{create.isPending ? <Card className="scan-beam p-8"><LoadingState label="Comparing URL signals" /></Card> : result ? <ResultCard scan={result} onDetails={() => setLocation(`/features/${result.id}`)} /> : <Card className="grid min-h-[410px] place-items-center p-8 text-center"><div><div className="pulse-ring mx-auto grid h-16 w-16 place-items-center rounded-full border border-[hsl(var(--primary)/.28)] bg-[hsl(var(--primary)/.07)] text-[hsl(var(--primary))]"><ShieldCheck size={30} strokeWidth={1.6} /></div><h2 className="mt-6 text-xl font-extrabold tracking-[-.04em]">Your explanation will land here.</h2><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[hsl(var(--muted-foreground))]">We will show the verdict, confidence and the specific URL signals behind it.</p></div></Card>}</div></div></>;
}

function UrlIntelligenceSection({ intel, url }: { intel?: any; url?: string }) {
  if (!intel) return null;
  const queryParamsLabel = intel.queryParameterCount > 0
    ? `${intel.queryParameterCount} (${intel.queryParameterNames?.join(', ') || 'detected'})`
    : '0';

  const items = [
    { label: 'Domain', value: intel.registrableDomain || 'Unavailable', mono: true },
    { label: 'IP Address', value: intel.ipAddress || 'Unavailable', mono: Boolean(intel.ipAddress) },
    { label: 'Protocol', value: intel.protocol || 'Unavailable' },
    { label: 'Port', value: intel.port != null ? String(intel.port) : 'Unavailable', mono: true },
    { label: 'Path', value: intel.path || '/', mono: true },
    { label: 'Subdomains', value: intel.subdomainCount != null ? String(intel.subdomainCount) : '0' },
    { label: 'Query Params', value: queryParamsLabel },
    { label: 'IP Version', value: intel.ipVersion || 'Unavailable' },
    { label: 'HTTPS', value: intel.httpsEnabled ? 'Enabled' : 'Disabled' },
    { label: 'Fragment', value: intel.hasFragment ? 'Present' : 'None' },
  ];

  return (
    <div className="border-t border-[hsl(var(--border))] px-6 py-5" data-testid="section-url-intelligence">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-xs font-bold uppercase tracking-wider text-[hsl(var(--primary))]">URL Intelligence</h3>
          <p className="mt-0.5 text-[11px] text-[hsl(var(--muted-foreground))]">Technical network and structure summary</p>
        </div>
        <span className="mono rounded-md bg-[hsl(var(--secondary))] px-2 py-0.5 text-[10px] font-semibold text-[hsl(var(--muted-foreground))]">
          {intel.protocol || 'HTTP'} : {intel.port || 80}
        </span>
      </div>
      <div className="mt-4 grid gap-2.5 sm:grid-cols-2">
        {items.map(({ label, value, mono }) => (
          <div key={label} className="flex items-center justify-between rounded-xl border border-[hsl(var(--border)/.6)] bg-[hsl(var(--background)/.5)] px-3.5 py-2 text-xs">
            <span className="text-[hsl(var(--muted-foreground))]">{label}</span>
            <span className={`font-bold truncate max-w-[60%] text-right ${mono ? 'mono text-[11px]' : ''}`} title={value}>
              {value}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

function ResultCard({ scan, onDetails }: { scan: any; onDetails: () => void }) {
  const bad = isPhishing(scan.verdict); const confidence = Math.round(scan.confidence * (scan.confidence <= 1 ? 100 : 1)); const risk = Math.round(scan.riskScore);
  const sim = Math.round((scan.similarityScore ?? 0) * (scan.similarityScore && scan.similarityScore <= 1 ? 100 : 1));
  return <Card className={`overflow-hidden ${bad ? 'border-[hsl(var(--destructive)/.3)]' : 'border-[hsl(var(--primary)/.3)]'}`} testId="card-scan-result"><div className={`p-6 ${bad ? 'bg-[hsl(var(--destructive)/.07)]' : 'bg-[hsl(var(--primary)/.07)]'}`}><div className="flex items-start justify-between gap-4"><div className={`grid h-12 w-12 place-items-center rounded-2xl ${bad ? 'bg-[hsl(var(--destructive)/.13)] text-[hsl(var(--destructive))]' : 'bg-[hsl(var(--primary)/.13)] text-[hsl(var(--primary))]'}`}>{bad ? <ShieldAlert size={25} /> : <ShieldCheck size={25} />}</div><StatusPill verdict={scan.verdict} /></div><h2 className="mt-7 text-2xl font-extrabold tracking-[-.05em]">{bad ? 'Take a closer look before continuing.' : 'No strong phishing signals found.'}</h2><p className="mono mt-3 break-all text-xs text-[hsl(var(--muted-foreground))]">{scan.url}</p></div>{scan.brandImpersonation && <div className="border-t border-[hsl(var(--destructive)/.25)] bg-[hsl(var(--destructive)/.08)] p-6" data-testid="section-brand-impersonation"><div className="flex items-center gap-2 text-sm font-extrabold text-[hsl(var(--destructive))]"><ShieldAlert size={18} /><span>Brand Impersonation Detected</span></div><div className="mt-4 grid gap-3 rounded-xl border border-[hsl(var(--destructive)/.2)] bg-[hsl(var(--card))] p-4 sm:grid-cols-3"><div><span className="block text-[10px] font-semibold uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Possible impersonation</span><strong className="mt-1 block text-sm font-extrabold text-[hsl(var(--destructive))]" data-testid="text-impersonated-brand">{scan.impersonatedBrand}</strong></div><div><span className="block text-[10px] font-semibold uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Legitimate domain</span><strong className="mono mt-1 block text-xs font-bold text-[hsl(var(--foreground))]" data-testid="text-legitimate-domain">{scan.legitimateDomain}</strong></div><div><span className="block text-[10px] font-semibold uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Similarity</span><strong className="mt-1 block text-sm font-extrabold text-[hsl(var(--foreground))]" data-testid="text-similarity-score">{sim}%</strong></div></div>{scan.impersonationReason && <div className="mt-3 text-xs leading-relaxed text-[hsl(var(--muted-foreground))]"><strong className="text-[hsl(var(--foreground))]">Reason: </strong><span data-testid="text-impersonation-reason">{scan.impersonationReason}</span></div>}</div>}<div className="grid gap-5 p-6 sm:grid-cols-2"><div><div className="flex justify-between text-xs"><span className="font-bold">Confidence</span><strong>{confidence}%</strong></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className={`h-full rounded-full ${bad ? 'bg-[hsl(var(--destructive))]' : 'bg-[hsl(var(--primary))]'}`} style={{ width: `${confidence}%` }} /></div></div><div><div className="flex justify-between text-xs"><span className="font-bold">Risk score</span><strong>{risk}/100</strong></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className={`h-full rounded-full ${bad ? 'bg-[hsl(var(--destructive))]' : 'bg-[hsl(var(--primary))]'}`} style={{ width: `${risk}%` }} /></div></div></div><UrlIntelligenceSection intel={scan.urlIntelligence} url={scan.url} /><div className="border-t border-[hsl(var(--border))] px-6 py-5"><p className="text-xs font-bold">Why this result?</p>{scan.ruleFlags?.length ? <ul className="mt-3 space-y-2">{scan.ruleFlags.slice(0, 3).map((flag: string, index: number) => <li key={`${flag}-${index}`} className="flex gap-2 text-xs leading-5 text-[hsl(var(--muted-foreground))]"><span className="mt-1 h-1.5 w-1.5 shrink-0 rounded-full bg-[hsl(var(--accent))]" />{flag}</li>)}</ul> : <p className="mt-2 text-xs leading-5 text-[hsl(var(--muted-foreground))]">The model and URL rules did not find anything that needs your attention.</p>}<Button variant="outline" onClick={onDetails} className="mt-5 w-full" testId="button-view-scan-details">View full feature breakdown <ArrowRight size={14} /></Button></div></Card>;
}

function LogsPage() {
  const [search, setSearch] = useState(''); const [verdict, setVerdict] = useState<'all' | 'safe' | 'phishing'>('all'); const [minRisk, setMinRisk] = useState('');
  const params = useMemo(() => ({ search: search || undefined, verdict: verdict === 'all' ? undefined : verdict, minRisk: minRisk ? Number(minRisk) : undefined }), [search, verdict, minRisk]);
  const scans = useListScans(params, { query: { queryKey: getListScansQueryKey(params) } });
  return <><PageHeading eyebrow="Scan history" title="Your decisions, in context." copy="Search past checks, revisit a signal and notice the patterns that make you pause." action={<Link href="/scanner" data-testid="link-logs-scan" className="focus-ring inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-[13px] font-bold text-[hsl(var(--primary-foreground))]"><Radar size={15} /> Scan a URL</Link>} /><Card className="mb-5 p-4"><div className="grid gap-3 md:grid-cols-[1fr_170px_170px]"><label className="relative"><Search size={16} className="absolute left-3 top-3 text-[hsl(var(--muted-foreground))]" /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search a domain or URL" data-testid="input-search-logs" className="focus-ring h-10 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] pl-9 pr-3 text-xs outline-none" /></label><select value={verdict} onChange={e => setVerdict(e.target.value as typeof verdict)} data-testid="select-verdict-filter" className="focus-ring h-10 rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 text-xs font-semibold outline-none"><option value="all">All verdicts</option><option value="safe">Looks safe</option><option value="phishing">Phishing signals</option></select><select value={minRisk} onChange={e => setMinRisk(e.target.value)} data-testid="select-risk-filter" className="focus-ring h-10 rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3 text-xs font-semibold outline-none"><option value="">Any risk score</option><option value="25">25+ risk</option><option value="50">50+ risk</option><option value="75">75+ risk</option></select></div></Card>{scans.isLoading ? <LoadingState label="Finding matching scans" /> : scans.isError ? <ErrorState onRetry={() => scans.refetch()} /> : scans.data?.length ? <Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-[hsl(var(--border))] px-5 py-4"><div className="flex items-center gap-2 text-xs font-bold"><ListFilter size={15} className="text-[hsl(var(--primary))]" /> {scans.data.length} matching scans</div><span className="text-[11px] text-[hsl(var(--muted-foreground))]">Newest first</span></div>{scans.data.map((scan: any) => <ScanRow key={scan.id} scan={scan} />)}</Card> : <EmptyState title="No scans match that filter" copy="Try a broader search or scan a new URL to begin a fresh thread." action={<Link href="/scanner" data-testid="link-empty-logs-scan" className="text-xs font-bold text-[hsl(var(--primary))]">Open the scanner <ArrowRight size={13} className="ml-1 inline" /></Link>} />}</>;
}

function FeaturesPage() {
  const { id } = useParams<{ id: string }>(); const scan = useGetScan(id ?? '', { query: { enabled: Boolean(id), queryKey: getGetScanQueryKey(id ?? '') } });
  const sim = Math.round(((scan.data as any)?.similarityScore ?? 0) * ((scan.data as any)?.similarityScore && (scan.data as any)?.similarityScore <= 1 ? 100 : 1));
  return <>{scan.isLoading ? <LoadingState label="Loading scan explanation" /> : scan.isError || !scan.data ? <ErrorState onRetry={() => scan.refetch()} label="That scan could not be found." /> : <><PageHeading eyebrow="Feature breakdown" title="See what shaped the call." copy="Every result is a set of signals. This view keeps the evidence visible and understandable." action={<Link href="/logs" data-testid="link-back-logs" className="focus-ring inline-flex items-center gap-2 rounded-xl border border-[hsl(var(--border))] px-4 py-2.5 text-[13px] font-bold"><ChevronRight size={15} className="rotate-180" /> Back to history</Link>} /><Card className="overflow-hidden"><div className="flex flex-col justify-between gap-5 border-b border-[hsl(var(--border))] p-6 md:flex-row md:items-start md:p-8"><div className="min-w-0"><StatusPill verdict={scan.data.verdict} /><h2 className="mt-4 break-all text-xl font-extrabold tracking-[-.04em]">{scan.data.url}</h2><p className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">Scanned {fmtDate(scan.data.createdAt)} at {fmtTime(scan.data.createdAt)}</p></div><div className="flex gap-5 md:text-right"><div><p className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Risk score</p><p className="mt-1 text-3xl font-extrabold tracking-[-.06em]">{Math.round(scan.data.riskScore)}<span className="text-sm text-[hsl(var(--muted-foreground))]">/100</span></p></div><div><p className="text-[10px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]">Confidence</p><p className="mt-1 text-3xl font-extrabold tracking-[-.06em]">{Math.round(scan.data.confidence * (scan.data.confidence <= 1 ? 100 : 1))}<span className="text-sm text-[hsl(var(--muted-foreground))]">%</span></p></div></div></div><div className="grid gap-8 p-6 md:grid-cols-[.9fr_1.1fr] md:p-8"><div><h3 className="text-sm font-extrabold">Decision context</h3><div className="mt-4 space-y-3"><ContextLine label="Rules engine" value={scan.data.rulePrediction} /><ContextLine label="ML prediction" value={scan.data.mlPrediction} /><ContextLine label="Signals found" value={`${scan.data.ruleFlags?.length ?? 0} rule flags`} />{scan.data.brandImpersonation && <ContextLine label="Brand impersonation" value="phishing" />}</div>{scan.data.brandImpersonation && <div className="mt-5 rounded-xl border border-[hsl(var(--destructive)/.3)] bg-[hsl(var(--destructive)/.08)] p-4" data-testid="features-brand-impersonation"><div className="flex items-center gap-2 text-xs font-extrabold text-[hsl(var(--destructive))]"><ShieldAlert size={16} /> Brand Impersonation Detected</div><div className="mt-3 space-y-1.5 text-xs text-[hsl(var(--muted-foreground))]"><p>Target brand: <strong className="text-[hsl(var(--foreground))]">{scan.data.impersonatedBrand}</strong></p><p>Legitimate domain: <strong className="mono text-[hsl(var(--foreground))]">{scan.data.legitimateDomain}</strong></p><p>Similarity: <strong className="text-[hsl(var(--foreground))]">{sim}%</strong></p>{scan.data.impersonationReason && <p className="mt-2 border-t border-[hsl(var(--destructive)/.2)] pt-2 leading-relaxed text-[hsl(var(--foreground))]"><strong className="text-[hsl(var(--muted-foreground))]">Reason: </strong>{scan.data.impersonationReason}</p>}</div></div>}{scan.data.ruleFlags?.length ? <div className="mt-7 rounded-xl bg-[hsl(var(--destructive)/.07)] p-4"><p className="text-xs font-bold text-[hsl(var(--destructive))]">Signals worth noticing</p><ul className="mt-3 space-y-2">{scan.data.ruleFlags.map((flag: string, index: number) => <li key={`${flag}-${index}`} className="flex gap-2 text-xs leading-5 text-[hsl(var(--muted-foreground))]"><ShieldAlert size={14} className="mt-0.5 shrink-0 text-[hsl(var(--destructive))]" />{flag}</li>)}</ul></div> : <div className="mt-7 rounded-xl bg-[hsl(var(--primary)/.07)] p-4 text-xs leading-5 text-[hsl(var(--muted-foreground))]"><CheckCircle2 size={16} className="mb-2 text-[hsl(var(--primary))]" /><p className="font-bold text-[hsl(var(--foreground))]">No rule flags were raised.</p>The URL structure looks familiar to the checks we run.</div>}</div><div><h3 className="text-sm font-extrabold">Extracted URL features</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">The raw inputs the model used for this decision.</p><div className="mt-4 overflow-hidden rounded-xl border border-[hsl(var(--border))]">{Object.keys(scan.data.features ?? {}).length ? Object.entries(scan.data.features).map(([key, value]) => <div key={key} className="flex items-center justify-between gap-4 border-b border-[hsl(var(--border)/.7)] px-4 py-3 last:border-0"><span className="mono text-[11px] text-[hsl(var(--muted-foreground))]">{key}</span><span className="max-w-[55%] break-all text-right text-xs font-bold">{String(value)}</span></div>) : <p className="p-5 text-xs text-[hsl(var(--muted-foreground))]">Feature details are not available for this scan.</p>}</div></div></div><UrlIntelligenceSection intel={scan.data.urlIntelligence} url={scan.data.url} /></Card></>}</>;
}

function ContextLine({ label, value }: { label: string; value: string }) {
  const bad = isPhishing(value); return <div className="flex items-center justify-between rounded-xl border border-[hsl(var(--border))] px-4 py-3"><span className="text-xs text-[hsl(var(--muted-foreground))]">{label}</span><span className={`text-xs font-bold ${bad ? 'text-[hsl(var(--destructive))]' : 'text-[hsl(var(--primary))]'}`}>{bad ? 'phishing signal' : 'looks safe'}</span></div>;
}

function ModelInfoPage() {
  const model = useGetModelInfo({ query: { queryKey: getGetModelInfoQueryKey(), retry: 1 } }); const data = model.data;
  return <><PageHeading eyebrow="Model notes" title="A model you can look behind." copy="A compact view of how PhishGuard was evaluated and which URL signals carry the most weight." />{model.isLoading ? <LoadingState label="Loading model notes" /> : model.isError ? <ErrorState onRetry={() => model.refetch()} /> : data ? <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Accuracy" value={pct(data.accuracy)} note="Overall test-set accuracy" icon={Target} /><Metric label="Precision" value={pct(data.precision)} note="When it says phishing" icon={Target} /><Metric label="Recall" value={pct(data.recall)} note="Phishing links caught" icon={Radar} /><Metric label="F1 score" value={pct(data.f1Score)} note="Balance of precision and recall" icon={Gauge} tone="amber" /></div><div className="mt-6 grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><Card className="p-6"><p className="mono text-[10px] uppercase tracking-[.17em] text-[hsl(var(--primary))]">Training snapshot</p><h2 className="mt-3 text-xl font-extrabold tracking-[-.04em]">What the model has seen</h2><div className="mt-7 space-y-4"><DataLine label="Dataset size" value={data.datasetSize != null ? data.datasetSize.toLocaleString() : '—'} /><DataLine label="Phishing examples" value={data.phishingCount != null ? data.phishingCount.toLocaleString() : '—'} /><DataLine label="Legitimate examples" value={data.legitimateCount != null ? data.legitimateCount.toLocaleString() : '—'} /><DataLine label="Last trained" value={fmtDate(data.trainedAt)} /></div><div className="mt-6 rounded-xl bg-[hsl(var(--secondary))] p-4 text-xs leading-5 text-[hsl(var(--muted-foreground))]"><BookOpen size={15} className="mb-2 text-[hsl(var(--primary))]" /><strong className="text-[hsl(var(--foreground))]">How to read this.</strong> Metrics describe test performance, not certainty about one individual URL. Always use the explanation as a prompt to pause.</div></Card><Card className="p-6"><div className="flex items-start justify-between"><div><p className="mono text-[10px] uppercase tracking-[.17em] text-[hsl(var(--primary))]">Feature importance</p><h2 className="mt-3 text-xl font-extrabold tracking-[-.04em]">What gets attention first</h2></div><Sparkles size={18} className="text-[hsl(var(--accent-foreground))]" /></div><div className="mt-7 space-y-4">{data.featureImportance?.map((item: any) => <div key={item.name}><div className="mb-1.5 flex justify-between text-xs"><span className="mono text-[11px]">{item.name}</span><span className="font-bold text-[hsl(var(--muted-foreground))]">{Math.round(item.importance * (item.importance <= 1 ? 100 : 1))}%</span></div><div className="h-2 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--primary))]" style={{ width: `${Math.min(100, item.importance * (item.importance <= 1 ? 100 : 1))}%` }} /></div></div>)}</div></Card></div><Card className="mt-6 overflow-hidden"><div className="border-b border-[hsl(var(--border))] px-6 py-4"><h2 className="text-sm font-extrabold">Feature dictionary</h2><p className="mt-1 text-[11px] text-[hsl(var(--muted-foreground))]">A plain-language glossary for the extracted signals.</p></div>{data.features?.map((item: any) => <div key={item.name} className="grid gap-1 border-b border-[hsl(var(--border)/.7)] px-6 py-4 last:border-0 sm:grid-cols-[.35fr_1fr]"><span className="mono text-[11px] font-medium text-[hsl(var(--primary))]">{item.name}</span><span className="text-xs leading-5 text-[hsl(var(--muted-foreground))]">{item.description}</span></div>)}</Card></> : <EmptyState title="Model notes are unavailable" copy="There is no evaluation snapshot to show right now." />}</>;
}

function DataLine({ label, value }: { label: string; value: string }) { return <div className="flex items-center justify-between border-b border-[hsl(var(--border)/.7)] pb-3 text-xs last:border-0"><span className="text-[hsl(var(--muted-foreground))]">{label}</span><strong>{value}</strong></div>; }

function SettingsPage() {
  const [, setLocation] = useLocation(); const user = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), retry: false } }); const logout = useLogout(); const [dark, setDark] = useState(document.documentElement.classList.contains('dark')); const [saved, setSaved] = useState(false);
  const toggleTheme = () => { const next = !dark; setDark(next); document.documentElement.classList.toggle('dark', next); setSaved(true); setTimeout(() => setSaved(false), 1800); };
  return <><PageHeading eyebrow="Workspace settings" title="Make PhishGuard yours." copy="Small preferences for the way you read a result and move through your workspace." />{user.isLoading ? <LoadingState /> : <div className="grid gap-6 lg:grid-cols-[.72fr_1.28fr]"><Card className="p-6"><div className="flex items-center gap-4"><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[hsl(var(--primary)/.12)] text-lg font-extrabold text-[hsl(var(--primary))]">{user.data?.name?.slice(0, 1).toUpperCase() ?? 'U'}</div><div><h2 className="font-extrabold" data-testid="text-settings-name">{user.data?.name ?? 'Your account'}</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]" data-testid="text-settings-email">{user.data?.email ?? 'Signed in workspace'}</p></div></div><div className="mt-8 rounded-xl bg-[hsl(var(--secondary))] p-4 text-xs leading-5 text-[hsl(var(--muted-foreground))]"><UserRound size={16} className="mb-2 text-[hsl(var(--primary))]" />Your account keeps scans connected across the dashboard, history and explanations.</div></Card><div className="space-y-6"><Card className="p-6"><div className="flex items-start justify-between"><div><h2 className="text-sm font-extrabold">Appearance</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Choose the surface that feels clearest to you.</p></div><Moon size={18} className="text-[hsl(var(--primary))]" /></div><button onClick={toggleTheme} data-testid="button-toggle-theme" className="focus-ring mt-5 flex w-full items-center justify-between rounded-xl border border-[hsl(var(--border))] p-4 text-left transition hover:border-[hsl(var(--primary)/.4)]"><span className="flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[hsl(var(--secondary))]"><Monitor size={15} /></span><span><span className="block text-xs font-bold">{dark ? 'Dark cockpit' : 'Light cockpit'}</span><span className="mt-1 block text-[11px] text-[hsl(var(--muted-foreground))]">{dark ? 'Deep teal surfaces, low glare' : 'Warm paper, crisp contrast'}</span></span></span><span className={`h-5 w-9 rounded-full p-0.5 transition ${dark ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--muted))]'}`}><span className={`block h-4 w-4 rounded-full bg-[hsl(var(--card))] transition ${dark ? 'translate-x-4' : ''}`} /></span></button>{saved && <p className="mt-3 text-[11px] font-bold text-[hsl(var(--primary))]" data-testid="status-theme-saved">Appearance saved for this session.</p>}</Card><Card className="p-6"><h2 className="text-sm font-extrabold">Session</h2><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Sign out of this browser on a shared device.</p><Button variant="danger" onClick={() => logout.mutate(undefined, { onSuccess: () => setLocation('/') })} disabled={logout.isPending} className="mt-5" testId="button-settings-logout"><LogOut size={15} /> {logout.isPending ? 'Signing out…' : 'Sign out'}</Button></Card></div></div>}</>;
}

function ForgotPasswordPage() {
  const [, setLocation] = useLocation(); const [email, setEmail] = useState('');
  return <AuthLayout eyebrow="Account recovery" title="Let’s get you back in." copy="Enter your email and we will show the next step. This demo flow keeps your account details private."><form onSubmit={e => { e.preventDefault(); setLocation(`/verify-otp?email=${encodeURIComponent(email)}`); }} className="space-y-4"><Field label="Email address" value={email} onChange={setEmail} type="email" placeholder="you@example.com" testId="input-forgot-email" /><Button type="submit" className="w-full" testId="button-send-otp">Continue to verification <ArrowRight size={15} /></Button></form><p className="mt-7 text-center text-xs text-[hsl(var(--muted-foreground))]"><Link href="/login" data-testid="link-back-login" className="font-bold text-[hsl(var(--primary))]">Back to sign in</Link></p></AuthLayout>;
}

function VerifyOtpPage() {
  const [, setLocation] = useLocation(); const [otp, setOtp] = useState('');
  return <AuthLayout eyebrow="Account recovery · 02" title="Check your inbox." copy="Enter the six-digit code from the recovery email. For this demo, any six digits will continue."><form onSubmit={e => { e.preventDefault(); setLocation('/reset-password'); }} className="space-y-4"><label className="block"><span className="mb-2 block text-xs font-bold">Verification code</span><input required minLength={6} maxLength={6} value={otp} onChange={e => setOtp(e.target.value.replace(/\D/g, ''))} inputMode="numeric" placeholder="000000" data-testid="input-otp" className="focus-ring mono h-12 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-4 text-center text-lg tracking-[.45em] outline-none" /></label><Button type="submit" disabled={otp.length !== 6} className="w-full" testId="button-verify-otp">Verify code <Check size={15} /></Button></form><p className="mt-7 text-center text-xs text-[hsl(var(--muted-foreground))]">Didn’t receive it? <button onClick={() => setOtp('')} data-testid="button-resend-otp" className="font-bold text-[hsl(var(--primary))]">Send again</button></p></AuthLayout>;
}

function ResetPasswordPage() {
  const [, setLocation] = useLocation(); const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const valid = password.length >= 6 && password === confirm;
  return <AuthLayout eyebrow="Account recovery · 03" title="Choose a fresh password." copy="Use at least six characters. You can return to the scanner as soon as you are done."><form onSubmit={e => { e.preventDefault(); setLocation('/login'); }} className="space-y-4"><Field label="New password" value={password} onChange={setPassword} type="password" placeholder="At least 6 characters" testId="input-reset-password" /><Field label="Confirm password" value={confirm} onChange={setConfirm} type="password" placeholder="Repeat your password" testId="input-confirm-password" />{confirm && password !== confirm && <p className="text-xs font-semibold text-[hsl(var(--destructive))]" data-testid="status-password-mismatch">Passwords do not match yet.</p>}<Button type="submit" disabled={!valid} className="w-full" testId="button-reset-password">Save new password <Check size={15} /></Button></form></AuthLayout>;
}

function ExtensionPreviewPage() {
  const [enabled, setEnabled] = useState(false); const [url, setUrl] = useState('https://paypaI-account-check.com/verify');
  return <><PageHeading eyebrow="Browser helper preview" title="A pause, closer to the click." copy="A static concept of the PhishGuard browser companion. It keeps the explanation lightweight and close to the moment you need it." action={<Button onClick={() => setEnabled(!enabled)} variant={enabled ? 'soft' : 'primary'} testId="button-toggle-extension">{enabled ? <Check size={15} /> : <Zap size={15} />} {enabled ? 'Helper enabled' : 'Enable preview'}</Button>} /><div className="mx-auto max-w-4xl"><div className="overflow-hidden rounded-[28px] border border-[hsl(var(--border))] bg-[#e9edf0] shadow-[0_24px_70px_rgba(28,53,64,.15)]"><div className="flex items-center gap-2 border-b border-[#d5dce0] bg-[#f7f8f8] px-5 py-3"><div className="flex gap-1.5"><span className="h-2.5 w-2.5 rounded-full bg-[#d0d7da]" /><span className="h-2.5 w-2.5 rounded-full bg-[#d0d7da]" /><span className="h-2.5 w-2.5 rounded-full bg-[#d0d7da]" /></div><div className="mx-auto flex h-8 max-w-xl flex-1 items-center gap-2 rounded-lg border border-[#d8dfe1] bg-white px-3 text-[11px] text-[#758188]"><LockKeyhole size={12} className="text-[#178b78]" />{url}<span className="ml-auto"><RefreshCw size={12} /></span></div><span className="grid h-7 w-7 place-items-center rounded-md bg-[#dce9e5] text-[#167d6e]"><ShieldCheck size={15} /></span></div><div className="grid min-h-[460px] place-items-center bg-[#f2f5f4] p-8"><div className="w-full max-w-[440px] rounded-2xl border border-[#d7e0dd] bg-[#fffefa] p-5 shadow-[0_14px_38px_rgba(36,73,77,.13)]"><div className="flex items-center gap-2 border-b border-[#e4e9e6] pb-4"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#dff1eb] text-[#147d6e]"><ShieldCheck size={17} /></span><div><p className="text-[12px] font-extrabold text-[#213c42]">PhishGuard</p><p className="text-[10px] text-[#7c8a8e]">A quick read before you continue</p></div><span className="ml-auto h-2 w-2 rounded-full bg-[#e2b34e]" /></div><div className="mt-5 rounded-xl bg-[#fff3ee] p-4"><div className="flex items-center gap-2 text-[#bd4e36]"><ShieldAlert size={18} /><span className="text-xs font-extrabold">Take a closer look</span></div><p className="mt-2 text-[11px] leading-5 text-[#796663]">This link has signals commonly seen in account impersonation attempts.</p></div><div className="mt-4 space-y-2.5"><div className="flex gap-2 text-[11px] text-[#68777a]"><span className="mt-1 h-1.5 w-1.5 rounded-full bg-[#e2b34e]" /> The domain uses a lookalike spelling.</div><div className="flex gap-2 text-[11px] text-[#68777a]"><span className="mt-1 h-1.5 w-1.5 rounded-full bg-[#e2b34e]" /> The sign-in path asks for urgency.</div></div><button onClick={() => setUrl('https://www.example.com/')} data-testid="button-extension-safe-example" className="mt-5 w-full rounded-lg bg-[#167d6e] py-2.5 text-[11px] font-bold text-white">View safer destination</button></div></div></div><div className="mt-8 grid gap-4 sm:grid-cols-3"><FeatureTile icon={Eye} title="Quiet by default" copy="Only speaks up when a URL deserves your attention." /><FeatureTile icon={Timer} title="A two-second pause" copy="Get the important context without leaving the page." /><FeatureTile icon={Code2} title="Built to explain" copy="Every nudge links back to the signals behind it." /></div></div></>;
}

function Router() {
  return <ErrorBoundary><Switch><Route path="/" component={LandingPage} /><Route path="/login" component={LoginPage} /><Route path="/signup" component={SignupPage} /><Route path="/forgot-password" component={ForgotPasswordPage} /><Route path="/verify-otp" component={VerifyOtpPage} /><Route path="/reset-password" component={ResetPasswordPage} /><Route path="/extension-preview" component={ExtensionPreviewPage} /><Route path="/dashboard"><AppShell><DashboardPage /></AppShell></Route><Route path="/scanner"><AppShell><ScannerPage /></AppShell></Route><Route path="/logs"><AppShell><LogsPage /></AppShell></Route><Route path="/features/:id"><AppShell><FeaturesPage /></AppShell></Route><Route path="/model-info"><AppShell><ModelInfoPage /></AppShell></Route><Route path="/settings"><AppShell><SettingsPage /></AppShell></Route><Route component={NotFound} /></Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><Router /></QueryClientProvider>;
}

export default App;